-- Inside Grey Room v66 — cross-role information audit.
-- Adds explicit suspect-to-suspect crosslinks for 029–044 and scenario-specific
-- private role guidance for 029–039. No canonical truth, trame, objective,
-- scoring rule or gameplay mechanic is changed.

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{relations}', '{"1": [{"slot": 2, "text": "Tu sais que plusieurs transferts que tu exécutais correspondaient aux opérations qu’il validait, sans connaître la méthode employée sur le terrain."}, {"slot": 3, "text": "Tu reconnais un circuit de paiement déjà utilisé par son équipe après une exécution, sans savoir qui avait donné l’ordre initial."}], "2": [{"slot": 1, "text": "Tu savais qu’il pouvait financer rapidement une opération, mais tu ne lui communiquais pas toujours la méthode prévue."}, {"slot": 3, "text": "Tu lui as demandé une intimidation. Tu soutiens ne pas avoir demandé l’escalade meurtrière qu’il a ensuite commise."}], "3": [{"slot": 1, "text": "Tu reconnais le circuit financier utilisé après certaines opérations, mais tu ignores ce qu’il savait du détail des violences."}, {"slot": 2, "text": "La consigne de pression vient de sa chaîne locale. Tu sais aussi que tu as disposé d’une marge d’action sur le terrain."}]}'::jsonb, true) where scenario_id='029';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{role_notes}', '{"juge": {"anchors": "Le Juge ne lance plus de convocation chronométrée depuis l’application. En temps libre, il va directement voir le joueur qu’il souhaite entendre. La Grey Room reste inaccessible sans convocation officielle."}, "expert": {"anchors": "Une expertise active par cycle. Une contre-expertise par partie. Tout joueur peut consulter naturellement l’Expert sans session chronométrée. L’Expert assiste aux interrogatoires et confrontations comme observateur technique et peut corriger une mauvaise interprétation sans mener lui-même l’interrogatoire."}, "maitre": {"anchors": "Le dossier distingue commandement, financement et geste matériel. Une implication dans le réseau n’établit pas automatiquement l’intention homicide.", "position": "Défends la frontière exacte entre ce que ton client savait, ce qu’il a demandé et ce qu’un autre a choisi d’exécuter."}, "suspect": {"anchors": "Hors Grey Room, les échanges avec l’Avocat sont libres et sans chronomètre. Tous les Suspects, qu’ils soient client officiel ou non, peuvent demander pendant leur propre interrogatoire une pause privée de 01:00 avec un Avocat, une fois par cycle. Le chrono de l’interrogatoire se suspend puis reprend exactement où il s’était arrêté. Pour un non-client, cette consultation ponctuelle ne crée pas de représentation."}, "analyste": {"anchors": "Compare les mots employés pour décrire la consigne : « faire peur », « intimider », « punir » et « tuer » n’engagent pas le même niveau de responsabilité.", "position": "Repère surtout les changements de version sur la consigne reçue, la marge d’action et le moment où chacun apprend le résultat."}, "enqueteur": {"anchors": "Sépare quatre maillons : financement, ordre initial, escalade et exécution matérielle. Un paiement après les faits ne prouve pas à lui seul qui a voulu la violence.", "position": "Fais reconstruire qui savait quoi avant l’opération, puis ce que chacun a choisi lorsque l’intimidation a dérapé."}, "procureur": {"anchors": "Une coopération peut être utile sans effacer les actes déjà établis. Cherche des informations vérifiables sur la chaîne de décision, pas seulement une accusation contre un supérieur.", "position": "Construis l’accusation maillon par maillon et distingue réduction de peine, crédibilité de la source et responsabilité pénale."}, "inspecteur": {"anchors": "Trois lieux maximum par cycle, chaque lieu une seule fois. Chaque résultat est transmis à l’Enquêteur ; l’Inspecteur choisit s’il l’élargit au reste du camp. En salle d’attente il peut confronter un ou deux suspects sans durée fixe, avec le risque d’une dénonciation du Journaliste et d’une pénalité de -10 au camp Enquête."}, "journaliste": {"anchors": "Rôle indépendant. Enquête libre sur le camp Enquête comme sur les suspects. Maximum 3 Breaking News par cycle et 6 sur la partie, publications scénarisées et rédigées comprises. Une publication rédigée doit déclarer sa base de source et n’est jamais transformée en vérité canonique. Une infraction journalistique signalée ne coûte -10 qu’après validation par le Juge, ou l’Enquêteur si aucun Juge n’est présent."}}'::jsonb, true) where scenario_id='029';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{relations}', '{"1": [{"slot": 2, "text": "Tu sais qu’il a organisé au moins une rencontre que les participants n’ont pas déclarée officiellement."}, {"slot": 3, "text": "Tu travailles avec des fonds qu’il met à disposition, sans recevoir de lui le détail de chaque pression ou faveur attendue."}], "2": [{"slot": 1, "text": "Tu sais qu’il approchait les acteurs judiciaires et qu’il utilisait des intermédiaires pour éviter les contacts directs."}, {"slot": 3, "text": "Tu connais l’objectif général qu’il cherchait à obtenir, sans pouvoir prouver qu’il a dicté chaque décision contestée."}], "3": [{"slot": 1, "text": "Tu lui confiais l’approche des intermédiaires et le choix des moyens les moins visibles."}, {"slot": 2, "text": "Tu savais qu’il pouvait faciliter des rencontres institutionnelles, mais tu ne contrôlais pas chacune de ses démarches."}]}'::jsonb, true) where scenario_id='030';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{role_notes}', '{"juge": {"anchors": "Une décision peut être discutable tout en restant juridiquement défendable. Ce qui compte ici est la preuve d’un échange, d’une pression ou d’une intervention extérieure.", "position": "Arbitre les demandes d’accès et les accusations sans traiter le soupçon institutionnel comme une preuve acquise."}, "expert": {"anchors": "Une expertise active par cycle. Une contre-expertise par partie. Tout joueur peut consulter naturellement l’Expert sans session chronométrée. L’Expert assiste aux interrogatoires et confrontations comme observateur technique et peut corriger une mauvaise interprétation sans mener lui-même l’interrogatoire."}, "maitre": {"anchors": "La présence d’un paiement, d’une rencontre ou d’une décision favorable ne suffit pas seule à établir une contrepartie.", "position": "Force l’enquête à démontrer le lien entre chaque élément et l’acte reproché à ton client, plutôt qu’à raisonner par contamination du réseau."}, "suspect": {"anchors": "Hors Grey Room, les échanges avec l’Avocat sont libres et sans chronomètre. Tous les Suspects, qu’ils soient client officiel ou non, peuvent demander pendant leur propre interrogatoire une pause privée de 01:00 avec un Avocat, une fois par cycle. Le chrono de l’interrogatoire se suspend puis reprend exactement où il s’était arrêté. Pour un non-client, cette consultation ponctuelle ne crée pas de représentation."}, "analyste": {"anchors": "Cherche les points où argent, peur et intérêt personnel se croisent. Deux acteurs peuvent participer à la même stratégie sans connaître la totalité de la chaîne.", "position": "Compare qui connaissait l’objectif, qui connaissait le moyen employé et qui pouvait encore refuser."}, "enqueteur": {"anchors": "Distingue décision achetée, décision juridiquement défendable, menace et simple contact. Une décision favorable au cartel n’est pas automatiquement une preuve de corruption.", "position": "Reconstitue la chaîne argent → intermédiaire → rencontre → décision ou menace, sans sauter directement du paiement au verdict judiciaire."}, "procureur": {"anchors": "Le dossier est plus solide lorsqu’il relie un acte précis à une contrepartie ou à une menace précise. Évite d’accuser sur la seule base d’une décision contestable.", "position": "Cherche la preuve du lien entre avantage, attente et action concrète ; distingue corruption de la pression parallèle exercée sur le témoin."}, "inspecteur": {"anchors": "Trois lieux maximum par cycle, chaque lieu une seule fois. Chaque résultat est transmis à l’Enquêteur ; l’Inspecteur choisit s’il l’élargit au reste du camp. En salle d’attente il peut confronter un ou deux suspects sans durée fixe, avec le risque d’une dénonciation du Journaliste et d’une pénalité de -10 au camp Enquête."}, "journaliste": {"anchors": "Les rencontres non déclarées, les sociétés sans activité réelle et la menace contre un témoin sont des pistes publiables seulement si leur base est identifiable.", "position": "Expose les conflits d’intérêts et les contradictions publiques sans transformer une information de presse en verdict judiciaire."}}'::jsonb, true) where scenario_id='030';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{relations}', '{"1": [{"slot": 2, "text": "Tu sais qu’il gérait concrètement le lieu de rétention lorsque tu as commencé à transmettre les exigences."}, {"slot": 3, "text": "Tu sais qu’il avait lancé l’opération avant ton arrivée dans le dossier, mais tu acceptes ensuite d’utiliser la captivité comme levier."}], "2": [{"slot": 1, "text": "Tu sais qu’il est arrivé après l’enlèvement et qu’il a ensuite participé aux exigences adressées à l’extérieur."}, {"slot": 3, "text": "Tu as reçu la victime dans un lieu de rétention après son initiative initiale et tu connais son rôle dans le déclenchement de l’opération."}], "3": [{"slot": 1, "text": "Tu l’as laissé transmettre les exigences une fois l’enlèvement déjà en cours."}, {"slot": 2, "text": "Tu savais qu’il gardait la victime et qu’il disposait matériellement d’occasions d’ouvrir ou de maintenir le lieu."}]}'::jsonb, true) where scenario_id='031';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{role_notes}', '{"juge": {"anchors": "Le Juge ne lance plus de convocation chronométrée depuis l’application. En temps libre, il va directement voir le joueur qu’il souhaite entendre. La Grey Room reste inaccessible sans convocation officielle."}, "expert": {"anchors": "Une expertise active par cycle. Une contre-expertise par partie. Tout joueur peut consulter naturellement l’Expert sans session chronométrée. L’Expert assiste aux interrogatoires et confrontations comme observateur technique et peut corriger une mauvaise interprétation sans mener lui-même l’interrogatoire."}, "maitre": {"anchors": "Entrer tardivement dans une opération, garder un lieu ou transmettre des exigences ne sont pas des actes équivalents. La chronologie protège autant qu’elle incrimine.", "position": "Défends la responsabilité exacte de ton client au moment où il agit, sans lui attribuer ni effacer les décisions prises par les autres."}, "temoin": {"anchors": "Le Témoin apporte un récit factuel limité. Il ne connaît ni la chaîne complète de décision ni la vérité finale du dossier."}, "suspect": {"anchors": "Hors Grey Room, les échanges avec l’Avocat sont libres et sans chronomètre. Tous les Suspects, qu’ils soient client officiel ou non, peuvent demander pendant leur propre interrogatoire une pause privée de 01:00 avec un Avocat, une fois par cycle. Le chrono de l’interrogatoire se suspend puis reprend exactement où il s’était arrêté. Pour un non-client, cette consultation ponctuelle ne crée pas de représentation."}, "analyste": {"anchors": "La phrase « j’obéissais » ne suffit pas : cherche le moment où une possibilité réelle de renoncer, libérer ou ne plus profiter de la situation apparaît.", "position": "Compare les fenêtres de choix de chaque acteur plutôt que leurs titres dans le réseau."}, "enqueteur": {"anchors": "Sépare trois moments : décider l’enlèvement, maintenir la rétention et utiliser ensuite la victime dans une négociation. Les responsabilités peuvent changer au fil du temps.", "position": "Fais préciser à chacun le moment exact où il comprend que la victime est retenue contre son gré et ce qu’il choisit alors de faire."}, "procureur": {"anchors": "La coopération utile doit apporter un fait vérifiable sur l’origine de l’enlèvement, le lieu de rétention ou une possibilité de libération.", "position": "Distingue instigateur, gardien et négociateur et poursuis chacun sur ce que les faits permettent réellement d’établir."}, "inspecteur": {"anchors": "Trois lieux maximum par cycle, chaque lieu une seule fois. Chaque résultat est transmis à l’Enquêteur ; l’Inspecteur choisit s’il l’élargit au reste du camp. En salle d’attente il peut confronter un ou deux suspects sans durée fixe, avec le risque d’une dénonciation du Journaliste et d’une pénalité de -10 au camp Enquête."}, "journaliste": {"anchors": "Rôle indépendant. Enquête libre sur le camp Enquête comme sur les suspects. Maximum 3 Breaking News par cycle et 6 sur la partie, publications scénarisées et rédigées comprises. Une publication rédigée doit déclarer sa base de source et n’est jamais transformée en vérité canonique. Une infraction journalistique signalée ne coûte -10 qu’après validation par le Juge, ou l’Enquêteur si aucun Juge n’est présent."}}'::jsonb, true) where scenario_id='031';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{relations}', '{"1": [{"slot": 2, "text": "Tu savais que ses services prolongeaient certaines détentions au-delà des ordres écrits, mais tu as continué à faire circuler des listes."}, {"slot": 3, "text": "Tu recevais des priorités politiques issues de son entourage et tu les traduisais ensuite en documents administratifs."}], "2": [{"slot": 1, "text": "Tu utilisais les listes qu’il validait, mais certaines prolongations venaient de tes propres décisions opérationnelles."}, {"slot": 3, "text": "Ses notes permettaient d’identifier les cibles prioritaires, sans détailler la manière dont la sécurité devait les traiter."}], "3": [{"slot": 1, "text": "Tu savais que ses documents transformaient des priorités politiques en personnes concrètement visées."}, {"slot": 2, "text": "Tu savais que la sécurité interprétait largement les directives, sans formaliser toi-même chaque détention ou mauvais traitement."}]}'::jsonb, true) where scenario_id='032';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{role_notes}', '{"juge": {"anchors": "La valeur des archives dépend de leur auteur, de leur date et de leur fonction. Une note politique, une liste administrative et un registre de détention ne prouvent pas la même chose.", "position": "Arbitre les responsabilités en distinguant influence, décision et mise en œuvre."}, "expert": {"anchors": "Une expertise active par cycle. Une contre-expertise par partie. Tout joueur peut consulter naturellement l’Expert sans session chronométrée. L’Expert assiste aux interrogatoires et confrontations comme observateur technique et peut corriger une mauvaise interprétation sans mener lui-même l’interrogatoire."}, "maitre": {"anchors": "Un Avocat a un seul client officiel. Une fois accepté, ce client reste rattaché à lui pour toute l’affaire et l’Avocat l’accompagne lors des procédures officielles qui le concernent. Hors Grey Room, les échanges sont libres et sans chronomètre avec le client comme avec les autres Suspects. Pendant son propre interrogatoire, tout Suspect peut demander un aparté privé de 01:00, une fois par cycle ; pour le client officiel, il s’agit simplement d’un aparté confidentiel avec son propre Avocat."}, "temoin": {"anchors": "Tu peux authentifier les versions des listes, les signatures, les corrections et les dates. Tu n’as pas assisté aux ordres oraux ni aux mauvais traitements.", "position": "Apporte des repères documentaires précis et refuse d’aller au-delà de ce que les archives et tes observations permettent."}, "suspect": {"anchors": "Hors Grey Room, les échanges avec l’Avocat sont libres et sans chronomètre. Tous les Suspects, qu’ils soient client officiel ou non, peuvent demander pendant leur propre interrogatoire une pause privée de 01:00 avec un Avocat, une fois par cycle. Le chrono de l’interrogatoire se suspend puis reprend exactement où il s’était arrêté. Pour un non-client, cette consultation ponctuelle ne crée pas de représentation."}, "analyste": {"anchors": "Cherche les écarts entre ce qui est écrit et ce qui est effectivement fait : une directive générale peut être aggravée en descendant la chaîne.", "position": "Compare surtout le moment où chaque acteur apprend les abus avec les actes qu’il accomplit ensuite."}, "enqueteur": {"anchors": "Les archives doivent permettre de séparer cible politique, ordre administratif et exécution sécuritaire. Une signature prouve un acte documentaire, pas automatiquement l’intention complète derrière les abus.", "position": "Fais dater les listes, corrections et prolongations et demande à chacun ce qu’il savait au moment où il a continué d’agir."}, "procureur": {"anchors": "Une responsabilité solide relie une personne à une décision concrète : désigner une cible, maintenir une liste, prolonger une détention ou couvrir les abus.", "position": "Construis une chaîne de décisions plutôt qu’une culpabilité collective de l’appareil d’État."}, "inspecteur": {"anchors": "Trois lieux maximum par cycle, chaque lieu une seule fois. Chaque résultat est transmis à l’Enquêteur ; l’Inspecteur choisit s’il l’élargit au reste du camp. En salle d’attente il peut confronter un ou deux suspects sans durée fixe, avec le risque d’une dénonciation du Journaliste et d’une pénalité de -10 au camp Enquête."}, "journaliste": {"anchors": "Rôle indépendant. Enquête libre sur le camp Enquête comme sur les suspects. Maximum 3 Breaking News par cycle et 6 sur la partie, publications scénarisées et rédigées comprises. Une publication rédigée doit déclarer sa base de source et n’est jamais transformée en vérité canonique. Une infraction journalistique signalée ne coûte -10 qu’après validation par le Juge, ou l’Enquêteur si aucun Juge n’est présent."}}'::jsonb, true) where scenario_id='032';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{relations}', '{"1": [{"slot": 2, "text": "Tu sais que certaines structures financées par la famille ont continué à recevoir des fonds après les premiers scandales publics."}, {"slot": 3, "text": "Tu savais que plusieurs dépenses sensibles étaient validées seulement après des échanges avec lui, malgré son absence de titre important."}], "2": [{"slot": 1, "text": "Tu savais que ses financements maintenaient des structures dont l’usage répressif était devenu difficile à ignorer."}, {"slot": 3, "text": "Tu le consultais sur plusieurs nominations et arbitrages sensibles, même lorsqu’aucun document officiel ne mentionnait son rôle."}], "3": [{"slot": 1, "text": "Tu savais que le contrôle des ressources lui donnait une influence politique indirecte."}, {"slot": 2, "text": "Tu savais qu’il pouvait protéger ou maintenir certains responsables par les nominations et les enquêtes administratives."}]}'::jsonb, true) where scenario_id='033';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{role_notes}', '{"juge": {"anchors": "Le pouvoir réel peut être informel. Inversement, un titre élevé ne suffit pas à attribuer une décision sans élément concret.", "position": "Pèse les actes documentés, les agendas et les interventions effectives plutôt que la place symbolique dans la famille."}, "expert": {"anchors": "Une expertise active par cycle. Une contre-expertise par partie. Tout joueur peut consulter naturellement l’Expert sans session chronométrée. L’Expert assiste aux interrogatoires et confrontations comme observateur technique et peut corriger une mauvaise interprétation sans mener lui-même l’interrogatoire."}, "maitre": {"anchors": "Un Avocat a un seul client officiel. Une fois accepté, ce client reste rattaché à lui pour toute l’affaire et l’Avocat l’accompagne lors des procédures officielles qui le concernent. Hors Grey Room, les échanges sont libres et sans chronomètre avec le client comme avec les autres Suspects. Pendant son propre interrogatoire, tout Suspect peut demander un aparté privé de 01:00, une fois par cycle ; pour le client officiel, il s’agit simplement d’un aparté confidentiel avec son propre Avocat."}, "temoin": {"anchors": "Tu peux confirmer les présences, reports, rendez-vous et modifications d’agenda. Tu ignores le contenu exact des conversations privées.", "position": "Aide à reconstruire le fonctionnement réel du pouvoir sans transformer une présence en décision automatique."}, "suspect": {"anchors": "Hors Grey Room, les échanges avec l’Avocat sont libres et sans chronomètre. Tous les Suspects, qu’ils soient client officiel ou non, peuvent demander pendant leur propre interrogatoire une pause privée de 01:00 avec un Avocat, une fois par cycle. Le chrono de l’interrogatoire se suspend puis reprend exactement où il s’était arrêté. Pour un non-client, cette consultation ponctuelle ne crée pas de représentation."}, "analyste": {"anchors": "Observe les décisions qui attendent l’avis d’une personne sans titre, les financements maintenus malgré les alertes et les protections administratives.", "position": "Cherche la répétition des dépendances : qui doit consulter qui avant d’agir réellement ?"}, "enqueteur": {"anchors": "Les liens de sang et les titres officiels ne suffisent pas. Reconstitue qui contrôlait les ressources, les nominations et les arbitrages avant chaque décision sensible.", "position": "Fais distinguer pouvoir formel, influence informelle et simple proximité familiale."}, "procureur": {"anchors": "Une influence devient juridiquement pertinente lorsqu’elle se rattache à une décision, un financement ou une protection précise.", "position": "Évite l’accusation par parenté et établis les actes propres de chaque membre du système."}, "inspecteur": {"anchors": "Trois lieux maximum par cycle, chaque lieu une seule fois. Chaque résultat est transmis à l’Enquêteur ; l’Inspecteur choisit s’il l’élargit au reste du camp. En salle d’attente il peut confronter un ou deux suspects sans durée fixe, avec le risque d’une dénonciation du Journaliste et d’une pénalité de -10 au camp Enquête."}, "journaliste": {"anchors": "Rôle indépendant. Enquête libre sur le camp Enquête comme sur les suspects. Maximum 3 Breaking News par cycle et 6 sur la partie, publications scénarisées et rédigées comprises. Une publication rédigée doit déclarer sa base de source et n’est jamais transformée en vérité canonique. Une infraction journalistique signalée ne coûte -10 qu’après validation par le Juge, ou l’Enquêteur si aucun Juge n’est présent."}}'::jsonb, true) where scenario_id='033';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{relations}', '{"1": [{"slot": 2, "text": "Tu sais qu’il centralisait des informations dont dépendaient certains dossiers que tu authentifiais, sans toujours connaître ses arbitrages."}, {"slot": 3, "text": "Tu as authentifié des décisions prises après plusieurs de ses passages au sommet, sans pouvoir conclure qu’il en était toujours l’auteur."}], "2": [{"slot": 1, "text": "Tu sais que son authentification rendait certaines opérations exécutables, même lorsqu’il n’en décidait pas le contenu."}, {"slot": 3, "text": "Tu recevais ou retenais des informations qui pouvaient modifier les recommandations qu’il présentait au sommet."}], "3": [{"slot": 1, "text": "Tu sais que son sceau validait matériellement certaines décisions sans prouver qu’il les avait conçues."}, {"slot": 2, "text": "Tu savais qu’il contrôlait une partie du flux d’information et que certaines alertes pouvaient ne jamais atteindre le sommet."}]}'::jsonb, true) where scenario_id='034';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{role_notes}', '{"juge": {"anchors": "Un surnom peut orienter l’enquête sans établir une responsabilité. La fonction exercée au moment de l’acte compte davantage que l’étiquette.", "position": "Exige que chaque attribution soit reliée à une opération, une date et un acte identifiable."}, "expert": {"anchors": "Une expertise active par cycle. Une contre-expertise par partie. Tout joueur peut consulter naturellement l’Expert sans session chronométrée. L’Expert assiste aux interrogatoires et confrontations comme observateur technique et peut corriger une mauvaise interprétation sans mener lui-même l’interrogatoire."}, "maitre": {"anchors": "Un Avocat a un seul client officiel. Une fois accepté, ce client reste rattaché à lui pour toute l’affaire et l’Avocat l’accompagne lors des procédures officielles qui le concernent. Hors Grey Room, les échanges sont libres et sans chronomètre avec le client comme avec les autres Suspects. Pendant son propre interrogatoire, tout Suspect peut demander un aparté privé de 01:00, une fois par cycle ; pour le client officiel, il s’agit simplement d’un aparté confidentiel avec son propre Avocat."}, "temoin": {"anchors": "Tu connais les circuits de transmission et l’usage variable des surnoms. Tu n’as pas assisté à toutes les délibérations du sommet.", "position": "Aide à démonter la fausse hiérarchie sans attribuer toi-même les décisions finales."}, "suspect": {"anchors": "Hors Grey Room, les échanges avec l’Avocat sont libres et sans chronomètre. Tous les Suspects, qu’ils soient client officiel ou non, peuvent demander pendant leur propre interrogatoire une pause privée de 01:00 avec un Avocat, une fois par cycle. Le chrono de l’interrogatoire se suspend puis reprend exactement où il s’était arrêté. Pour un non-client, cette consultation ponctuelle ne crée pas de représentation."}, "analyste": {"anchors": "Une même étiquette peut masquer des pouvoirs différents selon l’opération. Les contradictions apparentes peuvent venir d’un changement de fonction plutôt que d’un mensonge.", "position": "Compare les surnoms, les dates et les actes concrets avant de signaler une incohérence."}, "enqueteur": {"anchors": "Traite chaque surnom comme une fonction à dater, pas comme une identité permanente. Pour chaque opération, demande qui authentifie, qui contrôle l’information et qui recommande.", "position": "Fais reconstruire la fonction exercée lors de chaque dossier avant d’attribuer une décision à une personne."}, "procureur": {"anchors": "L’accusation doit relier une personne à une fonction et à un acte précis lors de l’opération concernée. Le prestige d’un surnom n’est pas une preuve.", "position": "Poursuis sur les décisions concrètes et les connaissances établies, pas sur la hiérarchie supposée des alias."}, "inspecteur": {"anchors": "Trois lieux maximum par cycle, chaque lieu une seule fois. Chaque résultat est transmis à l’Enquêteur ; l’Inspecteur choisit s’il l’élargit au reste du camp. En salle d’attente il peut confronter un ou deux suspects sans durée fixe, avec le risque d’une dénonciation du Journaliste et d’une pénalité de -10 au camp Enquête."}, "journaliste": {"anchors": "Les surnoms sont spectaculaires mais peuvent être trompeurs. Toute publication doit rattacher un alias à une opération et à une source identifiable.", "position": "Explique au public ce que les documents établissent réellement sans figer les surnoms en identités permanentes."}}'::jsonb, true) where scenario_id='034';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{relations}', '{"1": [{"slot": 2, "text": "Tu as reçu son alerte avant qu’elle disparaisse du circuit officiel et tu sais qu’elle visait précisément l’origine administrative de M-17."}, {"slot": 3, "text": "Tu as validé des documents transmis par son service sans connaître toutes les opérations couvertes par l’identité."}], "2": [{"slot": 1, "text": "Tu suspectes qu’il a enterré ton alerte après la pression hiérarchique, sans avoir vu directement l’ordre reçu."}, {"slot": 3, "text": "Tes vérifications montrent que plusieurs traces utilisées par son service ont été créées après les événements qu’elles décrivent."}], "3": [{"slot": 1, "text": "Tu sais qu’il peut être rendu responsable administrativement des renouvellements de M-17."}, {"slot": 2, "text": "Tu sais qu’il a signalé une anomalie puis retiré son rapport, sans connaître la méthode irrégulière utilisée pour la découvrir."}]}'::jsonb, true) where scenario_id='035';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{role_notes}', '{"expert": {"anchors": "Évalue l’authenticité documentaire, la chronologie de création et la cohérence des traces sans déduire une intention que les métadonnées ne prouvent pas.", "position": "Apporte un niveau de confiance sur les documents ; laisse l’enquête attribuer les décisions humaines."}, "analyste": {"anchors": "Repère les incohérences temporelles entre création des traces et événements prétendus, puis compare qui avait accès à chaque niveau du dossier.", "position": "Distingue erreur administrative, couverture consciente et usage opérationnel de l’identité."}, "enqueteur": {"anchors": "Ne confonds pas identité fabriquée et culpabilité automatique. Croise création des traces, renouvellements, dernière extraction et suppression de l’alerte.", "position": "Cherche qui savait que M-17 était une identité construite, qui a maintenu le dispositif et qui intervient dans ses dernières heures."}, "procureur": {"anchors": "Une identité fictive n’établit pas seule une participation au réseau. La continuité consciente, la suppression d’alerte et le dernier déplacement sont les actes à relier.", "position": "Distingue falsification administrative, couverture institutionnelle et participation opérationnelle."}}'::jsonb, true) where scenario_id='035';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{relations}', '{"1": [{"slot": 2, "text": "Tu sais qu’il a déclenché le plan d’urgence à 04:17, mais tu ignores d’abord qu’un couloir secondaire est resté sans surveillance."}, {"slot": 3, "text": "Tu apprends qu’un intervenant lié au site a quitté le périmètre pendant la crise, sans connaître immédiatement son rôle dans le mouvement discret."}], "2": [{"slot": 1, "text": "Tu sais qu’il a communiqué une attribution étrangère très tôt, avant que toutes les vérifications soient terminées."}, {"slot": 3, "text": "Tu connais l’existence du passage secondaire qu’il a emprunté, sans savoir ce qu’il transportait au moment de la diversion."}], "3": [{"slot": 1, "text": "Tu comptes sur l’attribution publique rapide pour détourner l’attention du mouvement effectué pendant la crise."}, {"slot": 2, "text": "Tu connaissais son calendrier de surveillance et savais qu’un redéploiement d’urgence pouvait ouvrir le couloir secondaire."}]}'::jsonb, true) where scenario_id='036';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{role_notes}', '{"expert": {"anchors": "Travaille sur l’authentification des sources, les horaires et les niveaux de confiance ; ne transforme pas une coïncidence temporelle en coordination prouvée.", "position": "Établis ce qui est fiable dans la chaîne technique et laisse la responsabilité aux recoupements humains."}, "analyste": {"anchors": "Sépare attribution publique, preuve matérielle et opportunité créée. Une erreur de communication peut être exploitée par quelqu’un sans avoir été organisée avec lui.", "position": "Compare les chronologies plutôt que les certitudes affichées par chacun."}, "enqueteur": {"anchors": "L’attaque est réelle mais peut aussi servir de diversion. Sépare attribution publique, faille de sûreté et mouvement effectué pendant les onze minutes sans surveillance.", "position": "Fais dater chaque connaissance : ce qui était cru à 04:24 n’a pas la même valeur que ce qui est appris à 05:10."}}'::jsonb, true) where scenario_id='036';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{relations}', '{"1": [{"slot": 2, "text": "Tu sais qu’il a ajusté son récit après avoir vu des photographies et tu as ensuite supprimé une contradiction de la transcription finale."}, {"slot": 3, "text": "Tu sais qu’elle contestait la procédure et disposait d’un élément antérieur que tu n’avais pas intégré au dossier."}], "2": [{"slot": 1, "text": "Tu as observé ce que son équipe savait déjà pendant le pré-entretien et tu as utilisé cette information pour calibrer une partie de ton récit."}, {"slot": 3, "text": "Tu ignores le contenu exact de sa source parallèle, mais tu comprends qu’elle sait qu’une partie d’ORPHÉE était connue avant ton arrestation."}], "3": [{"slot": 1, "text": "Tu sais qu’il a montré des photos avant l’entretien enregistré et qu’une contradiction a disparu de la version finale."}, {"slot": 2, "text": "Tu sais qu’une partie de son récit est authentique parce qu’un détail indépendant n’était pas connu de l’équipe d’interrogation."}]}'::jsonb, true) where scenario_id='037';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{role_notes}', '{"expert": {"anchors": "Compare versions, métadonnées, ordre d’apparition des informations et éléments indépendamment confirmés.", "position": "Évalue la fiabilité de chaque fragment sans transformer l’analyse en verdict global sur la source."}, "analyste": {"anchors": "Cherche ce qui était connu avant l’entretien pour mesurer la valeur des réponses, et repère les formulations qui apparaissent seulement après exposition à une information.", "position": "Distingue mémoire propre, suggestion procédurale et mensonge stratégique."}, "enqueteur": {"anchors": "Une confession peut être utile et contaminée à la fois. Sépare ce que la source savait avant l’entretien de ce qu’elle a pu apprendre pendant le pré-entretien.", "position": "Ne cherche pas à accepter ou rejeter tout le récit : classe chaque affirmation selon son origine et son recoupement."}}'::jsonb, true) where scenario_id='037';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{relations}', '{"1": [{"slot": 2, "text": "Tu sais que ses dérogations ont empêché plusieurs audits de remonter jusqu’à la coordination que tu maintenais."}, {"slot": 3, "text": "Tu lui confiais des liaisons entre relais, sans lui révéler nécessairement la totalité de la structure que tu protégeais."}], "2": [{"slot": 1, "text": "Tu savais que la coordination continuait après l’ordre officiel de fermeture et tu as maintenu une couverture administrative partielle."}, {"slot": 3, "text": "Tu savais que ses déplacements reliaient plusieurs nœuds que tes dérogations empêchaient de faire apparaître dans l’inventaire central."}], "3": [{"slot": 1, "text": "Tu recevais de sa chaîne les liaisons opérationnelles et tu savais que certains relais avaient été réactivés pendant la crise."}, {"slot": 2, "text": "Tu savais que ses dérogations protégeaient administrativement des moyens que tu continuais à déplacer sur le terrain."}]}'::jsonb, true) where scenario_id='038';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{role_notes}', '{"expert": {"anchors": "Les liens administratifs, opérationnels et documentaires n’ont pas la même valeur. Identifie ce qu’un document relie réellement avant d’en déduire une chaîne.", "position": "Aide à qualifier la force des liens ; ne transforme pas la proximité réseau en connaissance totale."}, "analyste": {"anchors": "Compare ce que chacun savait au moment où il a continué à agir : la connaissance de la fermeture, de la réactivation et de la finalité d’ORPHÉE n’est pas distribuée de manière égale.", "position": "Repère les moments où un rôle supposé administratif devient une décision de continuité."}, "enqueteur": {"anchors": "Le réseau est une structure de responsabilités, pas une culpabilité collective. Sépare maintien stratégique, couverture institutionnelle et exécution des liaisons.", "position": "Fais préciser ce que chacun savait au moment où il a choisi de continuer après l’ordre officiel de fermeture."}, "procureur": {"anchors": "La continuité consciente après fermeture est le point central. Relie chaque personne à l’acte qu’elle maintient malgré l’ordre officiel.", "position": "Distingue participation au réseau, couverture et décision de poursuivre ORPHÉE."}}'::jsonb, true) where scenario_id='038';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{relations}', '{"1": [{"slot": 2, "text": "Tu dépends de son contrôle du site pour qu’une éventuelle option de crise reste matériellement possible, sans lui avoir exposé toute la finalité politique."}, {"slot": 3, "text": "Tu sais qu’il protège politiquement ORPHÉE et qu’il a bloqué une reprise de contrôle institutionnelle."}], "2": [{"slot": 1, "text": "Tu savais qu’il contrôlait une partie de la chaîne de validation, mais tu n’en connaissais pas nécessairement l’objectif politique complet."}, {"slot": 3, "text": "Tu as accepté un transfert irrégulier dont sa protection politique rendait la contestation plus difficile."}], "3": [{"slot": 1, "text": "Tu savais qu’il préparait une option de crise et tu cherchais à conserver ORPHÉE comme levier politique."}, {"slot": 2, "text": "Tu savais qu’il contrôlait concrètement le site, sans savoir jusqu’où il comprenait la finalité stratégique de ce qu’il protégeait."}]}'::jsonb, true) where scenario_id='039';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{role_notes}', '{"expert": {"anchors": "Reste au niveau de la sûreté, des documents et des niveaux de confiance. Aucun détail de fonctionnement technique de l’actif n’est nécessaire au raisonnement.", "position": "Établis les dépendances humaines et documentaires sans fournir de procédure opérationnelle."}, "analyste": {"anchors": "Ne transforme pas l’urgence en certitude. Compare possession d’un levier, capacité d’action et intention réelle d’usage.", "position": "Cherche les asymétries de connaissance : deux personnes peuvent rendre une décision possible sans partager le même objectif."}, "enqueteur": {"anchors": "La conclusion repose sur la chaîne de décision et le niveau de connaissance, jamais sur une procédure technique. Sépare contrôle du site, validation et intention politique.", "position": "Fais établir qui pouvait autoriser, qui pouvait empêcher et qui comprenait réellement la finalité d’ORPHÉE."}, "procureur": {"anchors": "Distingue possession, couverture, autorité et intention d’usage. Une chaîne de validation partagée exige d’attribuer précisément les décisions.", "position": "Poursuis sur les actes humains démontrables : préparation illégale, transfert irrégulier ou blocage institutionnel."}}'::jsonb, true) where scenario_id='039';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{relations}', '{"1": [{"slot": 2, "text": "Tu le crois loyal mais sais qu’il te cache une dette ancienne et une présence qu’il explique mal."}, {"slot": 3, "text": "Tu sais qu’il a rencontré l’Oyabun en secret avant sa mort, sans connaître le contenu de cette rencontre."}], "2": [{"slot": 1, "text": "Tu crains qu’il découvre à qui tu devais une faveur et pourquoi tu étais près du lieu du meurtre."}, {"slot": 4, "text": "Tu ignores exactement ce qu’il a photographié, mais tu sais qu’il surveillait récemment des membres Kurokawa."}], "3": [{"slot": 1, "text": "Tu sais qu’il possède une partie du dossier de l’Oyabun et qu’il peut interpréter ta rencontre secrète comme une menace."}, {"slot": 4, "text": "Tu sais qu’il pousse Arakida à réagir fermement, parfois avant que les faits soient établis."}], "4": [{"slot": 2, "text": "Tu l’as vu près d’un véhicule officieux et sa version de ses déplacements ne t’explique pas cette proximité."}, {"slot": 3, "text": "Tu sais qu’il a rencontré l’Oyabun en secret et tu ignores si cette rencontre était une négociation ou une menace."}]}'::jsonb, true) where scenario_id='040';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{relations}', '{"1": [{"slot": 2, "text": "Tu as compris qu’il avait agi sous une obligation ancienne, mais tu ignores encore exactement qui a rappelé la dette."}, {"slot": 3, "text": "Tu sais que vos deux clans ont eux-mêmes conservé une dette commerciale discrète malgré leur rivalité."}], "2": [{"slot": 1, "text": "Tu crains qu’il découvre que la faveur qui t’a sauvé autrefois a été réactivée juste avant le meurtre."}, {"slot": 4, "text": "Tu sais qu’il cherche l’identité du relais et qu’il pourrait reconnaître le véhicule lié à ton ancien protecteur."}], "3": [{"slot": 1, "text": "Tu sais qu’il cherche à comprendre la dépendance de son Kobun tout en protégeant les propres obligations de Kurokawa."}, {"slot": 4, "text": "Tu sais qu’il dispose d’une piste concrète vers le relais policier et qu’il pourrait vouloir la monnayer."}], "4": [{"slot": 2, "text": "Tu peux relier le véhicule officieux à un relais susceptible d’avoir rappelé sa dette ancienne."}, {"slot": 3, "text": "Tu sais qu’il veut exposer la dépendance de Kurokawa tout en cachant certaines dettes de son propre clan."}]}'::jsonb, true) where scenario_id='041';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{relations}', '{"1": [{"slot": 2, "text": "Tu sais qu’il reconnaît le style du relais qui l’avait déjà utilisé et qu’il peut donc identifier une continuité dans les demandes."}, {"slot": 3, "text": "Tu sais qu’il a rejoint l’opération pour empêcher Kurokawa de monopoliser l’information, sans lui avoir confié tout ce que tu négociais."}], "2": [{"slot": 1, "text": "Tu sais qu’il a accepté l’opération en échange d’une information sur la mort de l’Oyabun."}, {"slot": 4, "text": "Tu soupçonnes qu’il suit davantage la chaîne des messages que la cible elle-même."}], "3": [{"slot": 1, "text": "Tu sais qu’il a accepté une demande officieuse et que Kurokawa espère recevoir une contrepartie informationnelle."}, {"slot": 4, "text": "Tu sais qu’il cherche l’origine policière des horaires et qu’un enregistrement pourrait faire tomber plusieurs versions."}], "4": [{"slot": 2, "text": "Tu sais qu’il a déjà été en contact avec le relais et qu’il peut reconnaître sa manière de procéder."}, {"slot": 3, "text": "Tu sais qu’il a fait circuler une copie partielle des documents et que cela peut créer une seconde chaîne de fuite."}]}'::jsonb, true) where scenario_id='042';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{relations}', '{"1": [{"slot": 2, "text": "Tu sais désormais qu’il est l’auteur matériel et qu’une dette extérieure a pesé sur sa décision, sans vouloir que cela efface son geste."}, {"slot": 3, "text": "Tu sais qu’il a préparé une riposte contre Kurokawa puis l’a suspendue lorsque les incohérences policières sont apparues."}], "2": [{"slot": 1, "text": "Tu veux qu’il reconnaisse que le clan t’a laissé dépendre d’un relais extérieur sans que cela devienne une excuse totale au meurtre."}, {"slot": 4, "text": "Tu sais que son enregistrement montre la relation clandestine qui peut expliquer pourquoi la couverture avait été préparée."}], "3": [{"slot": 1, "text": "Tu sais qu’il envisage d’isoler son propre Kobun pour sauver Kurokawa et le nom du clan."}, {"slot": 4, "text": "Tu comptes sur sa copie extérieure pour empêcher que l’affaire soit refermée sur un simple règlement entre clans."}], "4": [{"slot": 2, "text": "Tu sais qu’il est lié au relais par une dette ancienne et que ton enregistrement peut prouver la relation, pas l’ordre de meurtre à lui seul."}, {"slot": 3, "text": "Tu sais qu’il avait préparé une riposte violente mais qu’il l’a suspendue avant exécution."}]}'::jsonb, true) where scenario_id='043';

update public.igr_v4_scenario_packs set pack=jsonb_set(pack, '{relations}', '{"1": [{"slot": 2, "text": "Tu dois choisir entre l’isoler comme meurtrier matériel ou reconnaître la chaîne extérieure qui a activé sa dette."}, {"slot": 4, "text": "Tu sais que sa copie externe rend une version publique trop incomplète difficile à maintenir durablement."}], "2": [{"slot": 1, "text": "Tu veux qu’il reconnaisse que le clan t’a laissé dépendre du relais sans utiliser cette dépendance pour effacer ton propre geste."}, {"slot": 3, "text": "Tu sais qu’il veut empêcher qu’Arakida reste seulement un faux suspect et qu’il cherchera à exploiter politiquement la révélation."}], "3": [{"slot": 1, "text": "Tu sais qu’il prépare une version qui minimise le rôle policier et concentre la faute sur son propre Kobun."}, {"slot": 4, "text": "Tu comptes sur son enregistrement pour empêcher un accord trop favorable à la police, même si sa diffusion peut aussi servir tes intérêts."}], "4": [{"slot": 2, "text": "Tu sais qu’il conserve un dernier message du relais qui complète ton enregistrement sans supprimer sa responsabilité matérielle."}, {"slot": 3, "text": "Tu sais qu’il veut profiter politiquement de la révélation et qu’il pourrait pousser à une publication plus large."}]}'::jsonb, true) where scenario_id='044';
